const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No data received from Google Sheets. Check the sheet ID, tab name, and permissions.');
}
for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const keys = Object.keys(row).filter(k => k !== 'row_number');
  const colA = keys[0];
  const colB = keys[1];
  const colC = keys.length > 2 ? keys[2] : null;
  if (colB && row[colB] && row[colB].toString().toLowerCase().trim() === 'pending' && row[colA] && row[colA].toString().trim()) {
    const topic = row[colA].toString();
    const slug = topic.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').substring(0,60);
    const todayDate = DateTime.now().toFormat('yyyy-MM-dd');
    return [{json:{topic,rowNumber: row.row_number || (i+2),slug,todayDate,colA,colB,colC}}];
  }
}
throw new Error('No pending topics found in the CloudElite Topics sheet.');

const text = $input.first().json.text;
if (!text) throw new Error('No content received from Gemini (English). Check the AI model response.');
let clean = text.trim();
if (clean.startsWith('```')) {
  clean = clean.replace(/^```(?:md|markdown|mdx)?\n?/, '').replace(/\n?```$/, '');
}

// Defensive YAML frontmatter sanitizer.
// The prompt asks Gemini to quote every frontmatter value, but it sometimes
// forgets. An unquoted value containing ": " makes js-yaml throw
// ("incomplete explicit mapping pair"), which fails the entire Vercel build.
function quoteFrontmatterField(content, fieldName) {
  const regex = new RegExp('^(' + fieldName + ':)[ \\t]*(.*)$', 'm');
  return content.replace(regex, function(match, key, value) {
    const trimmed = value.trim();
    if (!trimmed) return match;
    if (trimmed.startsWith('"') && trimmed.endsWith('"')) return match;
    let inner = trimmed;
    if (inner.startsWith("'") && inner.endsWith("'")) inner = inner.slice(1, -1);
    inner = inner.replace(/\\"/g, '"').replace(/"/g, '\\"');
    return key + ' "' + inner + '"';
  });
}
const FRONTMATTER_FIELDS = ['title','excerpt','date','author','category','coverImage','coverImageCredit','coverImageCreditUrl'];
function sanitizeFrontmatter(md, label) {
  const m = md.match(/^(---\n)([\s\S]*?)(\n---)([\s\S]*)$/);
  if (!m) throw new Error(label + ' article has no YAML frontmatter block - refusing to push.');
  let fm = m[2];
  for (const field of FRONTMATTER_FIELDS) fm = quoteFrontmatterField(fm, field);
  return m[1] + fm + m[3] + m[4];
}

clean = sanitizeFrontmatter(clean, 'English');

let articleTitle = '';
const tm = clean.match(/^title:\s*"([^"]*)"/m);
if (tm) articleTitle = tm[1];
const t = $('Find First Pending Topic').first().json;
return [{json:{enContent:clean,articleTitle:articleTitle||t.topic,topic:t.topic,slug:t.slug,rowNumber:t.rowNumber,todayDate:t.todayDate,colA:t.colA,colB:t.colB,colC:t.colC}}];

