clean = sanitizeFrontmatter(clean, 'Arabic');

const en = $('Clean English Output').first().json;
return [{json:{...en,arContent:clean}}];

const data = $('Clean Arabic Output').first().json;
let hasImage = false;
let imageUrl = '';
let photographerName = '';
let photoUrl = '';
try {
  const r = $input.first().json;
  if (r && r.results && Array.isArray(r.results) && r.results.length > 0) {
    const f = r.results[0];
    if (f.urls && f.urls.regular) {
      imageUrl = f.urls.regular;
      hasImage = true;
      photographerName = (f.user && f.user.name) ? f.user.name : '';
      photoUrl = (f.links && f.links.html) ? f.links.html : '';
    }
  }
} catch(e) { hasImage = false; }

// The cover image is committed as public/images/blog/<slug>.jpg, so the
// frontmatter must point at exactly that path. Gemini invents its own filename
// instead of emitting the literal PLACEHOLDER, so the old replace() never
// matched and ~100 posts ended up referencing images that do not exist.
// Overwrite the field outright rather than pattern-matching PLACEHOLDER.
const coverImagePath = hasImage ? ('/images/blog/' + data.slug + '.jpg') : '';
const escName = photographerName.replace(/"/g, '\\"');
const credit = photographerName ? ('Photo by ' + escName + ' on Unsplash') : '';
const creditUrl = photoUrl || '';

// Quote-optional: matches `field: PLACEHOLDER` as well as `field: "PLACEHOLDER"`.
// The old regexes required the quotes, so unquoted placeholders survived into
// the published Arabic posts as the literal word PLACEHOLDER.
function setField(fm, field, value) {
  const re = new RegExp('^' + field + ':[ \\t]*.*$', 'm');
  if (!re.test(fm)) return fm;
  return fm.replace(re, function() { return field + ': "' + value + '"'; });
}

function sub(content) {
  // Normalize markdown: convert * bullets to - for consistent rendering
  let c = content.replace(/^(\s*)\*\s+/gm, '$1- ');
  const m = c.match(/^(---\n)([\s\S]*?)(\n---)([\s\S]*)$/);
  if (!m) return c;
  let fm = m[2];
  fm = setField(fm, 'coverImage', coverImagePath);
  fm = setField(fm, 'coverImageCredit', credit);
  fm = setField(fm, 'coverImageCreditUrl', creditUrl);
  return m[1] + fm + m[3] + m[4];
}

const enContent = sub(data.enContent);
const arContent = sub(data.arContent);
return [{json:{...data,enContent,arContent,hasImage,imageUrl,coverImagePath,imageFilePath:'public/images/blog/'+data.slug+'.jpg',photographerName,photoUrl}}];

const t = $('Find First Pending Topic').first().json;
const row = {};
row[t.colA] = t.topic;
row[t.colB] = 'used';
if (t.colC) row[t.colC] = DateTime.now().toFormat('yyyy-MM-dd');
return [{json:{...row,_topic:t.topic}}];
